const BEATS={"a1s1":[[2,"Theseus counts the days to his wedding"],[10,"Egeus demands the law against his daughter"],[17,"Theseus spells out Hermia's choices: obey, die or be a nun"],[23,"Lysander argues his case"],[27,"Alone, the lovers lament: true love never runs smooth"],[37,"Lysander's plan: escape to his aunt's house"],[42,"Helena wishes she were Hermia"],[52,"The lovers tell Helena their secret"],[58,"Helena decides to tell Demetrius"]],"a1s2":[[62,"The workmen meet to cast their play"],[70,"Bottom is Pyramus, and wants to be everyone else too"],[76,"Flute must play Thisbe, beard or no beard"],[89,"Snug gets the lion's part: just roaring"],[92,"Fear of frightening the ladies"],[99,"Rehearsal set for the palace wood"]],"a2s1":[[106,"A fairy meets Puck"],[108,"The quarrel over the changeling boy"],[113,"Oberon and Titania meet: \"Ill met by moonlight\""],[118,"Titania: our quarrel has wrecked the seasons"],[120,"Why Titania will not give up the boy"],[126,"Oberon sends Puck for the magic flower"],[133,"Demetrius rejects Helena"],[150,"Puck returns; Oberon gives him the juice for the Athenian"]],"a2s2":[[157,"The fairies sing Titania to sleep"],[165,"Oberon enchants Titania"],[170,"Lysander and Hermia, lost, lie down apart"],[180,"Puck anoints the wrong Athenian"],[183,"Demetrius abandons Helena"],[189,"Lysander wakes in love with Helena"],[194,"Lysander leaves Hermia asleep"],[196,"Hermia wakes from a nightmare, alone"]],"a3s1":[[201,"The workmen rehearse in the wood"],[205,"Problems: the sword, the lion, the moon and a wall"],[226,"Puck watches"],[240,"Bottom returns with an ass's head; his friends flee"],[253,"Bottom sings and wakes Titania"],[256,"Titania falls in love with Bottom"],[260,"Titania's fairies are ordered to serve him"]],"a3s2":[[283,"Puck tells Oberon: Titania loves a monster"],[292,"Demetrius pursues Hermia; Oberon sees the mistake"],[305,"Oberon sends Puck for Helena"],[310,"Oberon anoints Demetrius"],[316,"Lysander woos Helena"],[321,"Demetrius wakes in love with Helena too"],[322,"Helena thinks they are mocking her"],[329,"Hermia arrives; Lysander rejects her"],[334,"Helena accuses Hermia of joining the plot"],[358,"Hermia realises Lysander means it"],[362,"The quarrel over height"],[376,"The men go off to fight; the women flee"],[384,"Oberon orders fog and a cure"],[390,"Puck leads the rivals astray"],[413,"All four lovers fall asleep"],[419,"Puck cures Lysander's eyes"]],"a4s1":[[426,"Titania pampers Bottom"],[442,"Bottom and Titania fall asleep"],[445,"Oberon has the boy and pities Titania"],[447,"Titania is released; the fairies make peace"],[462,"Theseus goes hunting at dawn"],[467,"The sleeping lovers are found"],[476,"Lysander explains; Egeus demands the law"],[478,"Demetrius loves only Helena now"],[479,"Theseus overrules Egeus: three weddings"],[481,"The lovers wonder if they are awake"],[490,"Bottom wakes: \"a most rare vision\""]],"a4s2":[[494,"The workmen despair without Bottom"],[502,"News of the weddings"],[505,"Bottom returns: the play is on"]],"a5s1":[[513,"Theseus and Hippolyta discuss the lovers' story"],[514,"The lunatic, the lover and the poet"],[519,"Choosing the night's entertainment"],[530,"Theseus insists on the workmen's play"],[540,"The Prologue, mispunctuated"],[546,"The Prologue explains the whole plot"],[550,"Wall introduces himself"],[555,"Pyramus and Thisbe meet at the wall"],[581,"Lion and Moonshine explain themselves"],[600,"Thisbe flees the lion"],[611,"Pyramus finds the cloak and kills himself"],[627,"Thisbe kills herself"],[631,"A dance, and bed at midnight"],[637,"Puck sweeps the house"],[639,"Oberon and Titania bless the marriages"],[644,"Puck's epilogue"]]};
